134		a.current.Store(snap)
135		return nil
136	}
137	
138	// UnaryInterceptor enforces the static token on every non-whitelisted call.
139	func (a *Authenticator) UnaryInterceptor() grpc.UnaryServerInterceptor {
140		return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
141			snap := a.current.Load().(Snapshot)
142			if !snap.enabled {
143				return handler(ctx, req)
144			}
145			if snap.whitelist[info.FullMethod] {
146				return handler(ctx, req)
147			}
148			token, ok := extractToken(ctx)
149			if !ok {
150				return nil, status.Error(codes.Unauthenticated, "missing authorization credentials")
151			}
152			// Hash the client credential first so the comparison runs on
153			// fixed-length values and never leaks the token length.
154			sum := sha256.Sum256([]byte(token))
155			if subtle.ConstantTimeCompare(sum[:], snap.tokenHash[:]) != 1 {
156				return nil, status.Error(codes.Unauthenticated, "invalid token")
157			}
158			return handler(ctx, req)
159		}
160	}
161	
162	// extractToken pulls the credential from the "authorization" metadata,
163	// tolerating an optional "Bearer " prefix (any case).
164	func extractToken(ctx context.Context) (string, bool) {
165		md, ok := metadata.FromIncomingContext(ctx)
166		if !ok {
167			return "", false
168		}
169		vals := md.Get("authorization")
170		if len(vals) == 0 {
171			return "", false
172		}
173		token := strings.TrimSpace(vals[0])
174		if len(token) >= 7 && strings.EqualFold(token[:7], "bearer ") {
175			token = strings.TrimSpace(token[7:])
176		}
177		if token == "" {
178			return "", false
179		}
180		return token, true
181	}

